const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');
const n = parseInt(input.trim());

if (!isNaN(n)) {
    let a = 0n, b = 1n;
    let res = [];
    for (let i = 0; i < n; i++) {
        res.push(a.toString());
        let temp = a + b;
        a = b;
        b = temp;
    }
    console.log(res.join(' '));
}
